<section id="passports"><div class="section-heading"><div><p class="eyebrow"><?= $e($t('THE STORIES WE HOLD')) ?></p><h2><?= $e($t('Every story has people.')) ?></h2><p><?= $e($t('Get to know the voices, the context, and the choices behind each record.')) ?></p></div><span class="registry-count"><?= count($stories) ?> <?= $e($t('registered records')) ?></span></div><?php require __DIR__.'/search.php'; ?><div class="cards"><?php foreach ($stories as $i => $story): $restricted = $story['sensitivity'] === 'RESTRICTED'; ?><article class="card story-card"><div class="story-art art-<?= $i % 3 ?>"><?php if (!$restricted && $story['mediaType'] === 'image' && !empty($story['mediaUrl'])): ?><img src="<?= $e($story['mediaUrl']) ?>" alt="<?= $e($story['title']) ?>" loading="lazy"><?php else: ?><span class="story-art-glyph" aria-hidden="true"><?= $restricted ? '◈' : '“' ?></span><span class="story-art-label"><?= $e($restricted ? $t('HELD WITH CARE') : $t('A VOICE WORTH CARRYING')) ?></span><?php endif ?><span class="badge media-badge"><?= $e($restricted ? \Passport\Copy::SHARING[$story['accessState']??'RESTRICTED'] : ucfirst($story['mediaType'])) ?></span></div><div class="story-card-body"><p class="eyebrow"><?= $e($story['creator']['name']) ?></p><h3><?= $e($story['title'] ?? $t('restricted')) ?></h3><p><?= $e($restricted ? $t('Some stories stay close. Their stewards decide what can be shared.') : mb_strimwidth($story['contextNote'], 0, 145, '…')) ?></p><div class="card-bottom"><span class="status"><?= $e(\Passport\Copy::STATUS[$story['status']]) ?></span><a href="/p/<?= $e($story['id']) ?>" aria-label="<?= $e($t('Open passport for')) ?> <?= $e($story['title'] ?? $t('restricted')) ?>"><?= $e($t('passport')) ?> <span aria-hidden="true">↗</span></a></div></div></article><?php endforeach ?></div><?php if (!$stories): ?><div class="empty"><h3><?= $e($t('Every community starts with a story.')) ?></h3><p><?= $e($t('Make room for yours.')) ?></p><a class="button" href="/dashboard/new"><?= $e($t('register')) ?> ↗</a></div><?php endif ?></section>
